document.querySelectorAll('.ttw').forEach(wrap => {
  const trigger = wrap.querySelector('.ttb'), tip = wrap.querySelector('[role=tooltip]');
  let timer;
  const show = () => { clearTimeout(timer); tip.hidden = false; };
  const hide = () => { timer = setTimeout(() => { tip.hidden = true; }, 120); };
  trigger.addEventListener('mouseenter', show); trigger.addEventListener('focus', show);
  trigger.addEventListener('mouseleave', hide); trigger.addEventListener('blur', hide);
  tip.addEventListener('mouseenter', show); tip.addEventListener('mouseleave', hide);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') { clearTimeout(timer); tip.hidden = true; } });  /* dismissable without moving the pointer (WCAG 1.4.13) */
});
